    "lookDescription": "Volcano drift arena 180m — floating track segments over stylized lava sea y=-45m (orange #f97316 glow, heat shimmer). Three roll gates: torus rings tilted 90° roll-axis, purple storm cloud texture on ring surface — drone must barrel roll to align. Lava vents puff ash every 8sec — avoid 4m radius. Volcano rim silhouette hero at course midpoint. Dark sky #1e1b4b with ash fall particles. Neon racing stripe on track edges for visibility against orange below. Roll detected = ring rainbow flash + \"+ROLL\" popup. Non-roll pass = gate stays red, must retry.",
