    "lookDescription": "Storm cloud course 175m with ghost replay — translucent cyan #22d3ee alpha 0.4 ghost drone flies best previous lap path 0.5sec ahead. Live racing drone solid amber with neon stripe. Time delta HUD: \"+0.3s AHEAD\" green or \"-0.5s BEHIND\" red. Supercell wall at t=0.45 from drone mode 3. Eight rings in race configuration (tighter timing). Ghost flickers when live drone passes through same gate. Rain particles. Farmland vista below. Beat ghost = ghost shatters into particles at finish.",
