    "lookDescription": "Street grand prix rooftops 200m — enforced altitude band 1.5–3.5m (target 2m) shown as green translucent ribbon hugging roof surface. Racing drone skims AC units, vents, clotheslines — collision with red-tipped antenna hazards. Buildings rise 15–25m on sides creating canyon effect. Neon street signs on walls below. Altitude HUD bar center-bottom. Too high = \"TOO HIGH\" red flash; too low = scrape sparks. Six micro-gates between rooftops. Vista: street grid with moving car light trails far below. Tight and claustrophobic — opposite of open cloud modes.",
